package com.nazofobi.arrivalalarm

/** A passive provider only relays updates generated by other clients. */
internal object ActiveJourneyLocationProviderSelection {
    fun choose(enabledProviders: List<String>): String? = when {
        "gps" in enabledProviders -> "gps"
        "network" in enabledProviders -> "network"
        else -> enabledProviders.firstOrNull { it.isNotBlank() && it != "passive" }
    }
}
